const tasks=[{id:'XL–001',name:'急救物品配送',from:'大学城服务站',to:'大学城医院',type:'医疗专用货箱',status:'正在配送',state:'active',distance:'4.0',speed:16,battery:82,eta:12,step:2,path:'M185 220 Q320 160 405 315 T610 395',start:[185,220],end:[610,395],marker:[405,315]},{id:'XL–002',name:'文件与证件配送',from:'四川美术学院',to:'大学城图书馆',type:'重要文件货箱',status:'等待起飞',state:'waiting',distance:'2.6',speed:0,battery:96,eta:8,step:1,path:'M160 155 Q300 70 440 180 T550 285',start:[160,155],end:[550,285],marker:[160,155]},{id:'XL–003',name:'日常餐食配送',from:'大学城配送站',to:'社区服务中心',type:'日常配送货箱',status:'已送达',state:'done',distance:'1.8',speed:0,battery:65,eta:0,step:4,path:'M560 205 Q360 170 310 300 T180 420',start:[560,205],end:[180,420],marker:[180,420]}];let selected=tasks[0],filter='all',query='',toastTimer;const $=id=>document.getElementById(id);function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3000)}
function renderList(){const list=tasks.filter(t=>(filter==='all'||t.state===filter)&&`${t.id} ${t.name} ${t.to} ${t.from}`.toLowerCase().includes(query));$('task-list').innerHTML=list.length?list.map(t=>`<button class="task-card ${selected.id===t.id?'active':''}" data-task="${t.id}" aria-pressed="${selected.id===t.id}"><small>${t.id} / CONNECT</small><h3>${t.name}</h3><p><span>${t.to}</span><span>${t.status}</span></p></button>`).join(''):'<p class="no-results">没有匹配的任务。试试其他关键词或状态。</p>';document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{selected=tasks.find(t=>t.id===b.dataset.task);render();setView('overview')})}
function render(){renderList();$('detail-id').textContent=selected.id;$('delivery-name').textContent=selected.name;$('delivery-status').textContent=selected.status;$('cargo-type').textContent=selected.type;$('from-label').textContent=selected.from;$('to-label').textContent=selected.to;$('map-status-title').textContent=`${selected.id} ${selected.status}`;$('eta').innerHTML=`${selected.eta} <small>min</small>`;$('distance').innerHTML=`${selected.distance} <small>km</small>`;$('speed').innerHTML=`${selected.paused?0:selected.speed} <small>m/s</small>`;$('battery').innerHTML=`${selected.battery} <small>%</small>`;$('route-state').textContent=selected.paused?'演示已暂停':selected.state==='done'?'配送完成':selected.status;$('flight-route').setAttribute('d',selected.path);for(const [id,key] of [['map-start','start'],['map-end','end'],['drone-marker','marker']])$(id).setAttribute('transform',`translate(${selected[key].join(' ')})`);const steps=['需求已确认','航线已规划','无人机配送中','物品已送达'];$('progress-list').innerHTML=steps.map((s,i)=>`<li class="${i<=selected.step?'done':''}">${s}<small>${i<selected.step?'已完成':i===selected.step&&selected.step<3?'当前':''}</small></li>`).join('');$('pause-task').disabled=selected.state==='done';$('pause-task').textContent=selected.state==='done'?'配送已完成':selected.state==='waiting'?'开始演示任务':selected.paused?'继续演示任务':'暂停演示任务'}
function setView(view){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));['overview','routes','alerts'].forEach(v=>$(v+'-view').hidden=v!==view);$('view-title').textContent={overview:'每一段连接，尽在掌握。',routes:'把常用路线，留在手边。',alerts:'重要的信息，不错过。'}[view]}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderList()});$('task-search').oninput=e=>{query=e.target.value.trim().toLowerCase();renderList()};['2d','3d'].forEach(v=>$('map-'+v).onclick=()=>{$('map-area').classList.toggle('is-3d',v==='3d');['2d','3d'].forEach(n=>{$('map-'+n).classList.toggle('active',n===v);$('map-'+n).setAttribute('aria-pressed',String(n===v))})});$('pause-task').onclick=()=>{if(selected.state==='waiting'){selected.state='active';selected.status='正在配送';selected.speed=14;selected.step=2;toast('演示任务已开始')}else{selected.paused=!selected.paused;selected.status=selected.paused?'演示已暂停':'正在配送';toast(selected.paused?'演示任务已暂停':'演示任务已继续')}render();document.querySelector('.mini-summary small').textContent=`${tasks.filter(t=>t.state==='active').length} 进行中 · ${tasks.filter(t=>t.state==='waiting').length} 待起飞 · 1 已送达`};$('read-all').onclick=()=>{document.querySelector('[data-view="alerts"] i').textContent='0';toast('所有消息已标为已读')};$('saved-routes').innerHTML=tasks.map((t,i)=>`<article class="saved-route"><div><h3>${t.from} → ${t.to}</h3><button data-route="${i}">查看航线 ↗</button></div><p>${t.distance} km · ${t.type}<br>用于展示任务与航线的关联，非真实导航路线。</p></article>`).join('');document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{selected=tasks[Number(b.dataset.route)];filter='all';query='';$('task-search').value='';document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x.dataset.filter==='all'));render();setView('overview')});render();
